usage:
package main

import (
	"context"
	"fmt"
	"os"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey(os.Getenv("OPENAI_API_KEY")),
	)
	result, err := client.Projects.Groups.Roles.New(
		context.TODO(),
		"project_id",
		"group_id",
		openai.ProjectGroupRoleNewParams{
			RoleID: "string",
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
